window.products.push({"id":291490,"name":"Utopia Towels Cabana Stripe Beach Towel Bundle Orange, Yellow, Green & Blue (4-Pack) and Red, Navy, Grey & Plum (4-Pack)-100% Ring-Spun Cotton-Quick-D","category":"homeandappliances","retail price":63.29,"sale price":null,"image":"https://m.media-amazon.com/images/I/810zWF+I8yL._AC_SL1500_.jpg","description":"\"Utopia towel bundle offers 8-pack cabana stripe beach towels including Orange, Yellow, Green & Blue (4-pack) and Red, Navy, Grey & Plum (4-Pack). The premium quality of the towels is meant to give a luxury feel as it ideally wraps around the body. The large size of the towels and proficient construction makes them highly absorbent and quick drying while ensuring durability. The towels can be dynamically used for different purposes: after a shower while sunbathing on the beach or enjoying a day at the poolside. The vibrant colors of the towels notch up your style and flair. They are easily washable in the machine with warm water and light detergent on low. Avoid using bleach, fabric softener, or any other chemical, and refrain from ironing the towels. \"","images":["https://m.media-amazon.com/images/I/810zWF+I8yL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Utopia Towels","source_asin":"B0BH8TZQ7D","category_path":"Home & Kitchen"},"sku":"BM-291490","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BH8TZQ7D","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BH8TZQ7D","price_pending":true,"merchant_ready":false});
